"""Shared graph state: the contract every agent node reads from and writes to."""

from __future__ import annotations

from typing import TypedDict


class Source(TypedDict):
    title: str
    url: str
    snippet: str


class Findings(TypedDict):
    summary: str
    key_findings: list[str]


class ContentState(TypedDict, total=False):
    # Raw user request.
    request: str
    # Router classification: research | blog | linkedin | image (or "empty").
    intent: str
    # Topic extracted by the router.
    topic: str
    # Search queries generated by the Deep Research agent.
    queries: list[str]
    # Deduplicated search results; position i is citation [i + 1].
    sources: list[Source]
    # Synthesized research with [n] citations into `sources`.
    findings: Findings
    # Output format chosen by the post-research router (only "report" is wired).
    target_format: str
    # Final user-facing markdown.
    final_output: str
    # Non-fatal problems from the current run. Written only by run_searches; no reducer,
    # so each run replaces it (no stale errors accumulating on checkpointed threads).
    errors: list[str]
